```python
# 推斷：資料表=投入清單, 出貨檢驗（表頭第1列/第2列）｜欄位=工單號, SN, 問題點, 機種｜主檔=投入清單｜鍵=SN｜篩選=機種為A型｜輸出=新工作表
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

ws_input = wb["投入清單"]
ws_inspect = wb["出貨檢驗"]

# 讀取「投入清單」資料，建立以 SN 為鍵的字典
input_data = {}
for row in ws_input.iter_rows(min_row=2, values_only=True):
    if row[2] is not None:
        sn = row[2]
        work_order = row[1]
        model = row[3]
        input_data[sn] = {
            "工單號": work_order,
            "機種": model
        }

# 讀取「出貨檢驗」資料，建立以 SN 為鍵的字典
inspect_data = {}
for row in ws_inspect.iter_rows(min_row=3, values_only=True):
    if row[1] is not None:
        sn = row[1]
        work_order = row[0]
        problem = row[2]
        inspect_data[sn] = {
            "工單號": work_order,
            "問題點": problem
        }

# 合併兩表並篩選出「A型」的資料
results = []
for sn, input_info in input_data.items():
    if input_info["機種"] == "A型":
        inspect_info = inspect_data.get(sn, {})
        results.append([
            input_info["工單號"],
            sn,
            inspect_info.get("問題點", "")
        ])

# 建立新工作表
sheet_name = "A型分析結果"
if sheet_name in wb.sheetnames:
    del wb[sheet_name]
ws_new = wb.create_sheet(sheet_name)

# 寫入表頭與資料
ws_new.append(["工單號", "SN", "問題點"])
for r in results:
    ws_new.append(r)

wb.save(OUTPUT_PATH)
```
